fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let m = a.len();
    let n = b.len();
    
    // Both arrays must be non-empty (as stated in the problem)
    assert!(m > 0 && n > 0, "Both input arrays must be non-empty");
    
    // Arrays must be compatible (as stated in the assumption)
    assert!(m == n || m == 1 || n == 1, "Arrays must be compatible for broadcasting");
    
    let output_len = std::cmp::max(m, n);
    
    // Handle the three cases
    if m == n {
        // Case 1: Same length - copy both as-is
        (a, b)
    } else if m == 1 {
        // Case 2: First array has length 1, second is longer
        let repeated_a = vec![a[0]; output_len];
        (repeated_a, b)
    } else {
        // Case 3: Second array has length 1, first is longer
        let repeated_b = vec![b[0]; output_len];
        (a, repeated_b)
    }
}